$path='F:\Coding_SMA\axo_exambro\main.html'
$s=[IO.File]::ReadAllText($path)
$s=$s.Replace('<div class="field"><label>Username</label><input id="username" value="peserta01"','<div class="field"><label>Username</label><input id="username" value="" placeholder="Masukkan username"')
$s=$s.Replace('<div class="field"><label>Password</label><div class="passwordWrap"><input id="password" type="password" value="123456"','<div class="field"><label>Password</label><div class="passwordWrap"><input id="password" type="password" value="" placeholder="Masukkan password"')
$s=$s.Replace('<button onclick="opPage(''monitor'',this)"><span>05</span>Monitoring</button>','<button onclick="opPage(''monitor'',this)"><span>05</span>Monitoring</button><button onclick="opPage(''scores'',this)"><span>06</span>Rekap Nilai</button>')
$s=$s.Replace("if(page==='monitor')renderMonitor(el)","if(page==='monitor')renderMonitor(el);if(page==='scores')renderScores(el)")
$start=$s.IndexOf('function renderParticipant(){')
$end=$s.IndexOf('function startExam(id',$start)
if($start -ge 0 -and $end -gt $start){
$participant=@'
function networkStatus(){return navigator.onLine?'ONLINE':'OFFLINE'}function participantDashboardClock(){return new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}function renderParticipant(){clearInterval(liveTick);const results=get('axo_results',[]).filter(r=>r.username===activeUser.username);$('app').innerHTML=`<div class="loginSide" style="min-height:100vh;background:#091426;display:block;padding:0"><header class="topbar"><div class="brand" style="height:auto"><div class="brandLogo">AX</div><span>AxoExam</span></div><div class="topRight"><div class="badge ${navigator.onLine?'':'red'}">● ${networkStatus()}</div><button class="btn" onclick="openNetworkSettings()">Konfigurasi Jaringan</button><div class="clock">◷ <span id="participantClock"></span></div><div class="avatar">${escapeHTML(activeUser.name?.charAt(0)||'P')}</div><button class="btn btnDanger" onclick="logout()">Keluar</button></div></header><main class="content"><div class="pageHead"><div><h1>Dashboard Peserta</h1><p>${escapeHTML(activeUser.name)} · ${escapeHTML(activeUser.class||'-')} · ${escapeHTML(activeUser.username)}</p></div></div><div class="stats"><div class="stat"><div class="statTop">Mapel tersedia <b>EXAM</b></div><strong>${get('axo_exams',[]).length}</strong></div><div class="stat"><div class="statTop">Ujian selesai <b>SYNC</b></div><strong>${results.length}</strong></div><div class="stat"><div class="statTop">Nilai rata-rata <b>MAPEL</b></div><strong>${results.length?Math.round(results.reduce((a,r)=>a+r.score,0)/results.length):'-'}</strong></div><div class="stat"><div class="statTop">Status jaringan <b>${networkStatus()}</b></div><strong style="font-size:20px">${navigator.connection?.effectiveType||'Browser'}</strong></div></div><div class="card" style="margin-top:12px"><h3>Daftar Ujian & Nilai Mapel</h3><table class="table"><thead><tr><th>Ujian</th><th>Mata Pelajaran</th><th>Durasi</th><th>Nilai</th><th>Token</th><th>Aksi</th></tr></thead><tbody>${get('axo_exams',[]).map(e=>{const done=results.find(r=>r.examId===e.id);return `<tr><td><b>${escapeHTML(e.title)}</b></td><td>${escapeHTML(e.subject)}</td><td>${e.duration} menit</td><td><span class="badge ${done?'':'warn'}">${done?done.score:'Belum dikerjakan'}</span></td><td>${done?'Selesai':`<input id="token_${e.id}" class="search" style="width:150px;height:36px" placeholder="Token mapel">`}</td><td>${done?'':`<button class="btn btnPrimary" onclick="startExamFromInput('${e.id}')">Mulai Ujian</button>`}</td></tr>`}).join('')}</tbody></table></div></main></div>`;liveTick=setInterval(()=>{const c=document.getElementById('participantClock');if(c)c.textContent=participantDashboardClock()},1000)}function openNetworkSettings(){try{location.href='ms-settings:network-wifi'}catch(e){toast('Buka Windows Settings untuk mengatur Wi-Fi.',true)}}function startExamFromInput(id){const token=document.getElementById('token_'+id).value.trim();startExam(id,token)}
'@
$s=$s.Substring(0,$start)+$participant+$s.Substring($end)
}
$s=$s.Replace('function startExam(id){','function startExam(id,tokenInput){')
$s=$s.Replace("const token=prompt('Masukkan token mata pelajaran '+e.subject);if(token!==e.token)return toast('Token tidak sesuai.',true);","if(!tokenInput||tokenInput!==e.token)return toast('Token tidak sesuai.',true);")
$start=$s.IndexOf('function renderExam(){')
$end=$s.IndexOf('function updateTimer(){',$start)
if($start -ge 0 -and $end -gt $start){
$exam=@'
function questionAnswered(q){const a=currentAnswers[q.id];return a!=null&&(!Array.isArray(a)||a.length>0)}function updateQuestionMenu(){document.querySelectorAll('[data-question-id]').forEach(btn=>{const id=Number(btn.dataset.questionId),q=currentExam._questions.find(x=>x.id===id);btn.style.background=currentUnsure.has(id)?'#d89b2b':questionAnswered(q)?'#158b73':'';btn.style.color=currentUnsure.has(id)||questionAnswered(q)?'#fff':''})}function setAnswer(id,v){currentAnswers[id]=v;updateQuestionMenu()}function toggleComplex(id,v){const a=Array.isArray(currentAnswers[id])?[...currentAnswers[id]]:[];const n=a.indexOf(v);n>=0?a.splice(n,1):a.push(v);currentAnswers[id]=a;updateQuestionMenu()}function toggleUnsure(id){currentUnsure.has(id)?currentUnsure.delete(id):currentUnsure.add(id);renderExam()}function renderExam(){const q=currentExam._questions[currentIndex],isLast=currentIndex===currentExam._questions.length-1;$('app').innerHTML=`<div style="min-height:100vh;background:#091426"><header class="topbar"><div class="brand" style="height:auto"><div class="brandLogo">AX</div><span>${escapeHTML(currentExam.subject)}</span></div><div class="topRight"><div class="live"><i></i><span id="examClock">${clock()}</span></div><div class="clock" id="examTimer">00:00:00</div><button class="${isLast?'btn btnGreen':'btn btnDanger'}" onclick="manualSubmit()">${isLast?'Kirim Jawaban':'Kirim Jawaban'}</button></div></header><main class="content" style="max-width:1180px"><div style="display:grid;grid-template-columns:minmax(0,1fr)220px;gap:12px"><section><div class="pageHead"><div><h1>Soal ${currentIndex+1} / ${currentExam._questions.length}</h1><p class="mono">${escapeHTML(currentExam.title)}</p></div><button class="btn ${currentUnsure.has(q.id)?'btnDanger':''}" onclick="toggleUnsure(${q.id})">⚑ Ragu-ragu</button></div><div class="card" style="min-height:430px"><h3 style="font-size:17px">${escapeHTML(q.text)}</h3><div style="display:grid;gap:9px;margin-top:22px">${q.options.map((o,i)=>q.type==='PG'?`<label style="border:1px solid var(--line);border-radius:7px;padding:14px;display:flex;gap:10px"><input type="radio" name="answer" ${currentAnswers[q.id]===i?'checked':''} onchange="setAnswer(${q.id},${i})"><span>${escapeHTML(o)}</span></label>`:`<label style="border:1px solid var(--line);border-radius:7px;padding:14px;display:flex;gap:10px"><input type="checkbox" ${Array.isArray(currentAnswers[q.id])&&currentAnswers[q.id].includes(i)?'checked':''} onchange="toggleComplex(${q.id},${i})"><span>${escapeHTML(o)}</span></label>`).join('')}</div></div><div style="display:flex;justify-content:space-between;margin-top:12px"><button class="btn" ${currentIndex===0?'disabled':''} onclick="prevQuestion()">← Sebelumnya</button><button class="btn ${isLast?'btnGreen':'btnPrimary'}" onclick="${isLast?'manualSubmit()':'nextQuestion()'}">${isLast?'Kirim Jawaban':'Selanjutnya →'}</button></div></section><aside class="card" style="align-self:start;position:sticky;top:82px"><h3>Daftar Soal</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:7px">${currentExam._questions.map((item,i)=>`<button data-question-id="${item.id}" class="btn ${currentIndex===i?'btnPrimary':''}" style="padding:0" onclick="currentIndex=${i};renderExam()">${i+1}</button>`).join('')}</div><div style="margin-top:12px;font-size:11px;color:var(--muted);line-height:1.8"><span style="color:#158b73">■ Hijau: dijawab</span><br><span style="color:#d89b2b">■ Kuning: ragu-ragu</span><br><span>■ Biru: soal aktif</span></div></aside></div></main></div>`;updateQuestionMenu();clearInterval(timerTick);timerTick=setInterval(updateTimer,1000);updateTimer()}function prevQuestion(){if(currentIndex>0){currentIndex--;renderExam()}}function nextQuestion(){if(currentIndex<currentExam._questions.length-1){currentIndex++;renderExam()}}
'@
$s=$s.Substring(0,$start)+$exam+$s.Substring($end)
}
$s=$s+'\n'
[IO.File]::WriteAllText($path,$s,[Text.UTF8Encoding]::new($false))
